const {
  withPlugins,
  withAndroidManifest,
  withAppBuildGradle,
  withDangerousMod,
  withGradleProperties,
  withMainActivity,
  withMainApplication,
} = require('@expo/config-plugins');
const fs = require('fs');
const { readFileIfExists } = require('../utils/fs.cjs');
const path = require('path');

const { getDefaultAndroidApplicationId } = require('../../config/variants.cjs');

const PLUGIN_TAG = '[with-integrity-module-android]';

/**
 * PY-JP-013 — runtime code-integrity checks (OWASP "Insufficient Binary Protections").
 *
 * `android/` is gitignored and regenerated by `expo prebuild`, so the fix has to live here:
 * a hand-edit of MainActivity.kt or build.gradle is a fix with a countdown. Mirrors the
 * structure of `with-certificate-module-android/index.cjs`.
 */

/** @param {import('@expo/config-plugins').ExportedConfig} config */
function getAndroidApplicationPackage(config) {
  return config.android?.package || getDefaultAndroidApplicationId();
}

/** @param {string} androidPackage e.g. net.juspay.xynespaces */
function javaRootForPackage(platformProjectRoot, androidPackage) {
  const rel = androidPackage.split('.').join(path.sep);
  return path.join(platformProjectRoot, 'app', 'src', 'main', 'java', rel);
}

/** Normalize `AA:BB:...` / lowercase / whitespace into bare uppercase hex. */
function normalizeDigest(value) {
  return String(value).trim().replace(/[:\s]/g, '').toUpperCase();
}

function isValidDigest(value) {
  return /^[0-9A-F]{64}$/.test(value);
}

/** @param {import('@expo/config-plugins').ExportedConfig} config */
function getIntegrityOptions(config) {
  const enforced = config.extra?.lotusIntegrityEnforced === true;
  const raw = config.extra?.lotusIntegritySigningSha256 || '';
  const digests = String(raw).split(',').map(normalizeDigest).filter(Boolean);

  const invalid = digests.filter(d => !isValidDigest(d));
  if (invalid.length > 0) {
    throw new Error(
      `${PLUGIN_TAG} LOTUS_INTEGRITY_SIGNING_SHA256 contains ${invalid.length} malformed ` +
        `SHA-256 value(s). Each entry must be 64 hex characters (colons optional). ` +
        `First bad value: "${invalid[0]}"`,
    );
  }

  // Fail the build rather than shipping an enforced-but-unpinned APK, which would hard-block
  // every user on first launch.
  if (enforced && digests.length === 0) {
    throw new Error(
      `${PLUGIN_TAG} Integrity enforcement is enabled for this variant but no signing ` +
        `certificate is pinned. Set LOTUS_INTEGRITY_SIGNING_SHA256 in apps/mobile/.env.prod ` +
        `to the SHA-256 of the Play app signing certificate (Play Console -> Test and release ` +
        `-> Setup -> App integrity), optionally comma-separated with the upload keystore's ` +
        `certificate for locally built prodRelease APKs.`,
    );
  }

  // An explicitly empty value means "disable the install-origin check" (used to run release
  // builds locally over adb). Only an absent value falls back to the production default, so
  // `||` would be wrong here — it treats "" as unset.
  const rawInstallers = config.extra?.lotusIntegrityAllowedInstallers;
  const installers = String(rawInstallers === undefined ? 'com.android.vending' : rawInstallers)
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);

  return { enforced, digests, installers };
}

/** Insert an import directly after the `package` declaration (SDK-template agnostic). */
function ensureImport(contents, importLine) {
  if (contents.includes(importLine)) return contents;
  const lines = contents.split('\n');
  const pkgIndex = lines.findIndex(l => l.startsWith('package '));
  if (pkgIndex < 0) {
    throw new Error(`${PLUGIN_TAG} missing package declaration`);
  }
  lines.splice(pkgIndex + 1, 0, '', importLine);
  return lines.join('\n');
}

// --- 1. Kotlin sources ----------------------------------------------------------------------

const withIntegritySources = config =>
  withDangerousMod(config, [
    'android',
    async config => {
      const { projectRoot, platformProjectRoot } = config.modRequest;
      const androidPackage = getAndroidApplicationPackage(config);

      const sourceDir = path.join(projectRoot, 'plugins', 'android-modules', 'integrity');
      const targetDir = path.join(
        javaRootForPackage(platformProjectRoot, androidPackage),
        'integrity',
      );

      if (!fs.existsSync(targetDir)) {
        fs.mkdirSync(targetDir, { recursive: true });
      }

      const files = [
        'IntegrityGuard.kt',
        'TamperBlockActivity.kt',
        'IntegrityModule.kt',
        'IntegrityPackage.kt',
      ];

      for (const file of files) {
        const sourcePath = path.join(sourceDir, file);
        if (!fs.existsSync(sourcePath)) {
          throw new Error(`${PLUGIN_TAG} Source file not found: ${sourcePath}`);
        }
        fs.copyFileSync(sourcePath, path.join(targetDir, file));
      }

      return config;
    },
  ]);

// --- 2. MainActivity ------------------------------------------------------------------------

const withIntegrityMainActivity = config => {
  const androidPackage = getAndroidApplicationPackage(config);

  return withMainActivity(config, cfg => {
    let src = cfg.modResults.contents;
    src = ensureImport(src, `import ${androidPackage}.integrity.IntegrityGuard`);

    if (!src.includes('IntegrityGuard.check(this)')) {
      const before = src;
      // Top of onCreate, so none of the activity's own work (launch-intent capture, VoIP
      // handling) and nothing injected later in the method can run. Note expo-splashscreen's
      // generated block anchors on the same brace and ends up above this line; it performs no
      // application work, so the guard still precedes everything that matters.
      //
      // Deliberately ONE physical line. `withAppStartupTimingsAndroid` and expo-splashscreen
      // anchor on this same `onCreate` opening brace, and a multi-line block gets their
      // statements spliced between its braces — producing an `if` that swallows the rest of
      // the method and does not compile.
      //
      // super.onCreate MUST be called before returning: bailing out without it raises
      // SuperNotCalledException, which crashes the process, so the user sees a system
      // "app keeps stopping" dialog instead of the block screen. null avoids ReactActivity
      // restoring saved state on a build we have already rejected.
      src = src.replace(
        /(override fun onCreate\(savedInstanceState: Bundle\?\) \{\n)/,
        `$1    if (!IntegrityGuard.check(this)) { super.onCreate(null); IntegrityGuard.block(this); return }\n`,
      );
      if (src === before) {
        throw new Error(`${PLUGIN_TAG} Failed to inject IntegrityGuard into MainActivity.onCreate`);
      }
    }

    cfg.modResults.contents = src;
    return cfg;
  });
};

// --- 3. MainApplication ---------------------------------------------------------------------

const withIntegrityMainApplication = config => {
  const androidPackage = getAndroidApplicationPackage(config);

  return withMainApplication(config, cfg => {
    let src = cfg.modResults.contents;
    src = ensureImport(src, `import ${androidPackage}.integrity.IntegrityPackage`);
    src = ensureImport(src, `import ${androidPackage}.integrity.IntegrityGuard`);

    if (!src.includes('add(IntegrityPackage())')) {
      const before = src;
      src = src.replace(
        /PackageList\(this\)\.packages\.apply\s*\{\s*\n/,
        match => `${match}              add(IntegrityPackage())\n`,
      );
      if (src === before) {
        throw new Error(`${PLUGIN_TAG} Failed to register IntegrityPackage in MainApplication`);
      }
    }

    // Second call site: removing the MainActivity hook alone is not enough to disable the check.
    if (!src.includes('IntegrityGuard.check(this)')) {
      const before = src;
      src = src.replace(
        /(override fun onCreate\(\) \{\n\s*super\.onCreate\(\)\n)/,
        `$1    IntegrityGuard.check(this)\n`,
      );
      if (src === before) {
        throw new Error(
          `${PLUGIN_TAG} Failed to inject IntegrityGuard into MainApplication.onCreate`,
        );
      }
    }

    cfg.modResults.contents = src;
    return cfg;
  });
};

// --- 4. BuildConfig fields ------------------------------------------------------------------

const withIntegrityBuildConfig = config =>
  // Options are resolved inside the mod, not at plugin-composition time, so the
  // "no certificate pinned" error only fires during native generation (`expo prebuild`).
  // Resolving it eagerly would also throw for every plain config read — `expo start`,
  // Metro, and the `:expo-constants:createExpoConfig` Gradle task — breaking builds that
  // never touch signing at all.
  withAppBuildGradle(config, cfg => {
    const { enforced, digests, installers } = getIntegrityOptions(cfg);
    let contents = cfg.modResults.contents;

    // The third argument is a Groovy string holding Java source, so String fields need
    // escaped inner quotes: buildConfigField "String", "NAME", "\"value\""
    //
    // INTEGRITY_ENFORCED defaults to false here and is switched on only in buildTypes.release
    // (below). Enforcing in a debug build has no security value — a debug build is always
    // FLAG_DEBUGGABLE, so the guard could only ever block it — while breaking
    // `pnpm run android:prod:debug` for every developer.
    const fields = [
      { type: 'boolean', name: 'INTEGRITY_ENFORCED', literal: `"false"` },
      { type: 'String', name: 'INTEGRITY_SIGNING_SHA256', literal: `"\\"${digests.join(',')}\\""` },
      {
        type: 'String',
        name: 'INTEGRITY_ALLOWED_INSTALLERS',
        literal: `"\\"${installers.join(',')}\\""`,
      },
    ];

    for (const { type, name, literal } of fields) {
      const line = `buildConfigField "${type}", "${name}", ${literal}`;
      const existing = new RegExp(
        `^[ \\t]*buildConfigField\\s+"${type}",\\s+"${name}",\\s+.*$`,
        'm',
      );

      if (existing.test(contents)) {
        contents = contents.replace(existing, `        ${line}`);
      } else {
        const defaultConfigRegex = /(defaultConfig\s*\{\n)/;
        if (!defaultConfigRegex.test(contents)) {
          throw new Error(`${PLUGIN_TAG} app/build.gradle: missing defaultConfig`);
        }
        contents = contents.replace(defaultConfigRegex, `$1        ${line}\n`);
      }
    }

    // Turn enforcement on for release builds only. A buildConfigField in buildTypes.release
    // overrides the defaultConfig value above.
    const releaseLine = `buildConfigField "boolean", "INTEGRITY_ENFORCED", "${enforced}"`;
    const releaseFieldRegex = /^[ \t]*buildConfigField\s+"boolean",\s+"INTEGRITY_ENFORCED",\s+.*$/m;
    const releaseBlockRegex = /(\n {8}release \{\n)/;

    if (releaseFieldRegex.test(contents.split('buildTypes')[1] || '')) {
      // Already injected on a previous run — rewrite it in place.
      const [head, tail] = [
        contents.slice(0, contents.indexOf('buildTypes')),
        contents.slice(contents.indexOf('buildTypes')),
      ];
      contents = head + tail.replace(releaseFieldRegex, `            ${releaseLine}`);
    } else if (releaseBlockRegex.test(contents)) {
      contents = contents.replace(releaseBlockRegex, `$1            ${releaseLine}\n`);
    } else {
      throw new Error(`${PLUGIN_TAG} app/build.gradle: could not find buildTypes.release`);
    }

    cfg.modResults.contents = contents;
    return cfg;
  });

// --- 5. Manifest ----------------------------------------------------------------------------

const withTamperBlockActivity = config => {
  const androidPackage = getAndroidApplicationPackage(config);

  return withAndroidManifest(config, cfg => {
    const application = cfg.modResults.manifest.application?.[0];
    if (!application) {
      throw new Error(`${PLUGIN_TAG} AndroidManifest.xml: missing <application>`);
    }

    application.activity = application.activity || [];
    const name = `${androidPackage}.integrity.TamperBlockActivity`;
    if (!application.activity.some(a => a.$?.['android:name'] === name)) {
      application.activity.push({
        $: {
          'android:name': name,
          'android:exported': 'false',
          'android:excludeFromRecents': 'true',
          // Own task: MainActivity finishing (or any finishAffinity elsewhere) must not take
          // the block screen down with it.
          'android:taskAffinity': `${androidPackage}.integrity`,
          'android:launchMode': 'singleTask',
          'android:theme': '@android:style/Theme.DeviceDefault.Light.NoActionBar',
        },
      });
    }

    return cfg;
  });
};

// --- 6. R8 ----------------------------------------------------------------------------------

/**
 * Obfuscation is what stops the guard from being trivially deleted: in an unminified APK
 * `IntegrityGuard` appears in smali under that exact name, and removing one `invoke-static`
 * re-opens PY-JP-013. `apps/legacy` already ships R8 with the rules ported below.
 */
/** R8 needs far more heap than the Expo default; below this it dies with OutOfMemoryError. */
const MIN_R8_HEAP_MB = 6144;

const withIntegrityMinification = config =>
  withGradleProperties(config, cfg => {
    const findValue = key => {
      const item = cfg.modResults.find(p => p.type === 'property' && p.key === key);
      return item?.value;
    };

    // Expo's template ships `-Xmx2048m`, which is not enough to run R8 over this app's
    // dependency graph — the build fails with `R8: java.lang.OutOfMemoryError: Java heap
    // space` after ~29 minutes. Raise the ceiling, preserving any other JVM flags, and only
    // ever upward so a machine-specific larger value is left alone.
    const currentArgs = findValue('org.gradle.jvmargs') || '-Xmx2048m -XX:MaxMetaspaceSize=512m';
    const xmxMatch = currentArgs.match(/-Xmx(\d+)([mMgG])/);
    const currentMb = xmxMatch ? Number(xmxMatch[1]) * (/[gG]/.test(xmxMatch[2]) ? 1024 : 1) : 0;

    let nextArgs = currentArgs;
    if (currentMb < MIN_R8_HEAP_MB) {
      nextArgs = xmxMatch
        ? currentArgs.replace(xmxMatch[0], `-Xmx${MIN_R8_HEAP_MB}m`)
        : `-Xmx${MIN_R8_HEAP_MB}m ${currentArgs}`.trim();
    }
    if (!/MaxMetaspaceSize/.test(nextArgs)) {
      nextArgs = `${nextArgs} -XX:MaxMetaspaceSize=1g`;
    }

    cfg.modResults = cfg.modResults.filter(
      p =>
        !(
          p.type === 'property' &&
          (p.key === 'android.enableMinifyInReleaseBuilds' || p.key === 'org.gradle.jvmargs')
        ),
    );
    cfg.modResults.push(
      { type: 'property', key: 'android.enableMinifyInReleaseBuilds', value: 'true' },
      { type: 'property', key: 'org.gradle.jvmargs', value: nextArgs },
    );
    return cfg;
  });

const PROGUARD_START =
  '# --- BEGIN lotus integrity/mTLS keep rules (with-integrity-module-android) ---';
const PROGUARD_END = '# --- END lotus integrity/mTLS keep rules ---';

function buildProguardRules(androidPackage) {
  return `${PROGUARD_START}
# Ported from apps/legacy/android/app/proguard-rules.pro and extended for the modules that
# only exist in apps/mobile. Deliberately NO blanket keep on the .integrity package — keeping
# the guard's own class and method names would defeat the point of enabling R8.

# mTLS stack
-keep class ${androidPackage}.certificate.** { *; }
-keep class ${androidPackage}.http.** { *; }
-keep class ${androidPackage}.webview.** { *; }
-keep class ${androidPackage}.proxy.** { *; }
-keep class com.reactnativecommunity.webview.RNCWebViewClient { *; }
-keep class org.nanohttpd.** { *; }

# React Native packages registered by hand in MainApplication — these are resolved
# reflectively by the bridge, so their entry points must survive.
-keep class ${androidPackage}.AppStartupPackage { *; }
-keep class ${androidPackage}.AppStartupModule { *; }
-keep class ${androidPackage}.AppStartupTimes { *; }
-keep class ${androidPackage}.ShareTargetPackage { *; }
-keep class ${androidPackage}.sharetarget.** { *; }
-keep class ${androidPackage}.crashreporter.** { *; }
-keep class ${androidPackage}.downloads.** { *; }
-keep class ${androidPackage}.LaunchIntentPackage { *; }
-keep class ${androidPackage}.LaunchIntentModule { *; }
-keep class ${androidPackage}.CallNotificationDataPackage { *; }
-keep class ${androidPackage}.CallNotificationDataModule { *; }
-keep class ${androidPackage}.AuthContextPackage { *; }
-keep class ${androidPackage}.AuthContextModule { *; }
-keep class ${androidPackage}.IncomingCallUiPackage { *; }
-keep class ${androidPackage}.IncomingCallActivity { *; }
-keep class ${androidPackage}.VoIPForegroundServicePackage { *; }
-keep class ${androidPackage}.VoIPForegroundService { *; }

# The integrity module's RN bridge entry points only (not the guard itself).
-keep class ${androidPackage}.integrity.IntegrityPackage { *; }
-keep class ${androidPackage}.integrity.IntegrityModule { *; }
-keep class ${androidPackage}.integrity.TamperBlockActivity { *; }

# Prevent optimization of security classes
-dontoptimize
-keep class javax.net.ssl.** { *; }
-keep class org.bouncycastle.** { *; }

# Silence optional JNDI/LDAP references pulled in by BouncyCastle (Android lacks javax.naming)
-dontwarn javax.naming.**
-dontwarn javax.naming.directory.**
-dontwarn org.bouncycastle.jce.provider.X509LDAPCertStoreSpi
${PROGUARD_END}
`;
}

const withIntegrityProguardRules = config =>
  withDangerousMod(config, [
    'android',
    async config => {
      const androidPackage = getAndroidApplicationPackage(config);
      const rulesPath = path.join(
        config.modRequest.platformProjectRoot,
        'app',
        'proguard-rules.pro',
      );

      const existing = readFileIfExists(rulesPath) ?? '';
      const block = buildProguardRules(androidPackage);

      // Replace our own block if present, otherwise append — never clobber Expo's template
      // rules (reanimated / turbomodule keeps).
      const startIndex = existing.indexOf(PROGUARD_START);
      const next =
        startIndex === -1
          ? `${existing.trimEnd()}\n\n${block}`
          : `${existing.slice(0, startIndex)}${block}${existing.slice(
              existing.indexOf(PROGUARD_END) + PROGUARD_END.length,
            )}`;

      fs.writeFileSync(rulesPath, next);
      return config;
    },
  ]);

module.exports = config =>
  withPlugins(config, [
    withIntegritySources,
    withIntegrityMainActivity,
    withIntegrityMainApplication,
    withIntegrityBuildConfig,
    withTamperBlockActivity,
    withIntegrityMinification,
    withIntegrityProguardRules,
  ]);
